WFJ.Data.add("spell", {
  [1002] = { "$D1の間、ペットを直接操作し、その目を通して周囲を見ます。", "ペットを直接操作しています。", 0xd5cd7f27, 0x2553e1fb, "uu" },
  [1003] = { "Shadow Word: Befuddle（Rank 2）を習得します。", nil, 0x93c39130, nil, "um" },
  [1004] = { "敵を打ち据え、$N1のHolyダメージを与えます。", nil, 0x05e38ce8, nil, "um" },
  [1006] = { "Holyのエネルギーが術者を満たし、armorを$N1増加させます。プリーストが近接攻撃または遠隔攻撃のダメージを受けるたびに、チャージを1回消費します。効果時間は$D1、または$N3回のチャージを使い切るまでです。", "armorが$N1増加します。", 0x92b16b08, 0xa12ba50b, "uu" },
  [1008] = { "対象のパーティメンバーに向けられた魔法を増幅し、呪文から受けるダメージを最大$N1、治癒呪文による回復量を最大$N2増加させます。効果時間は$D1です。", "受ける魔法ダメージが最大$N1、受ける治療効果が最大$N2増加します。", 0xfcbd4f5d, 0x129e5d1f, "uu" },
  [1010] = { "対象に愚鈍の呪いをかけ、IntellectとSpiritを$N2秒ごとに$N1ずつ、それぞれ合計$N3下がるまで減少させます。同じ対象にかけられるCurseは、ウォーロックごとに1つだけです。", "IntellectとSpiritが低下しています。", 0x0a44f5ea, 0xe75db6a0, "uu" },
  [1014] = { "対象を苦痛で蝕み、$D1かけて$N1のShadowダメージを与えます。このダメージは最初はゆっくりと与えられ、Baneが効果時間の終わりに近づくにつれて増していきます。同じ対象にかけられるBaneは、ウォーロックごとに1つだけです。", "$D1かけて$N1のShadowダメージを受けます。", 0xd5b9a42b, 0x1df96f24, "uu" },
  [1020] = { "$D1の間、パラディンをすべてのダメージと呪文から守りますが、与えるダメージがすべて$N2%減少します。$D2の間Forbearanceを付与します。Forbearanceが有効な間は使用できません。", "すべての攻撃と呪文が効きませんが、与えるすべてのダメージが$N1%減少します。", 0x0bcdb662, 0x69b0b050, "uu" },
  [1022] = { "対象のパーティーメンバー一人を$D1の間すべての物理攻撃から守りますが、その間はそのメンバーも攻撃や物理アビリティの使用ができません。プレイヤーにかけられるBlessingは、同時にパラディン一人につき一つだけです。$D2の間Forbearanceを付与します。Forbearanceが有効な間は使用できません。", "物理攻撃が効きません。攻撃も物理的な技の使用もできません。", 0x272021e3, 0x3445333b, "uu" },
  [1026] = { "味方の対象を$N1回復します。", nil, 0xbe4c0f4a, nil, "um" },
  [1032] = { "$N2ヤード以内のパーティーメンバーのarmorを$N1増加させます。各プレイヤーにかけられるAuraは、パラディンごとに一度に一つだけです。", "armorが$N1増加します。", 0xc600442a, 0xa12a98e7, "uu" },
  [1037] = { "Seal of Fury（Rank 1）を習得します。", nil, 0x00ddca40, nil, "um" },
  [1038] = { "パーティメンバーにBlessingを授け、$D1の間、発生させるすべての脅威を$N1%減らします。プレイヤーが受けられるBlessingは、パラディン1人につき一度に1つだけです。", "発生する脅威が$N1%減少します。", 0x3d92bb5d, 0x69005136, "uu" },
  [1042] = { "味方の対象を$N1回復します。", nil, 0xbe4c0f4a, nil, "um" },
  [1044] = { "味方の対象にBlessingをかけ、$D1の間、移動を妨げる効果を無効にします。プレイヤーにかけられるBlessingは、パラディン一人につき同時に一つだけです。", "移動を妨げる効果が効きません。", 0x25b79994, 0xfedffc69, "uu" },
  [1058] = { "$D1かけて対象を$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x3367b9a9, 0x1302c045, "uu" },
  [1062] = { { "対象をその場に拘束し、$D1かけて$N1のNatureダメージを与えます。ダメージを受けると効果が解除されることがあります。同時にRootedにできる対象は最大$N3体です。", "対象をその場に拘束し、$D1かけて$N1のNatureダメージを与えます。ダメージを受けると効果が解除されることがあります。同時にRootedにできる対象は1体のみです。", shape = { "3/1", "3/1" } }, "その場から動けません。$N2秒ごとに$N1のNatureダメージを受けます。", 0x72d7ae6f, 0x6c03815b, "uu" },
  [1064] = { "味方の対象を$N1回復し、その後近くにいる別の対象へ跳躍して回復します。パーティメンバーに唱えた場合、回復は他のパーティメンバーにのみ跳躍します。各跳躍の効果は直前の対象の$N2%です。合計$N3体の対象を回復します。", nil, 0xa9f16400, nil, "um" },
  [1066] = { "水棲形態に変身し、泳ぐ速度を$N1%上げ、ドルイドが水中で呼吸できるようにします。また、術者をPolymorph効果から守ります。\n\n変身すると、術者はPolymorph効果とMovement Impairing効果から解放されます。", "Polymorphの効果が効きません。水泳速度が$N1%上昇し、水中で呼吸できます。", 0xbfc5de09, 0x11a64bd1, "uu" },
  [1070] = { "Faerie Fire（Rank 3）を習得します。", nil, 0xbe93bd35, nil, "um" },
  [1075] = { "味方の対象から棘が生え、攻撃してきた相手に$N1のNatureダメージを与えます。効果時間は$D1です。", "攻撃者に$N1のNatureダメージを与えます。", 0x0eddc25a, 0x763a853a, "uu" },
  [1079] = { "持続的にダメージを与えるフィニッシュ技です。ダメージはコンボポイントごと、およびAttack Powerによって増加します：\n $N1ポイント：$D1かけて$N2のダメージ。\n $N4ポイント：$D2かけて$N5のダメージ。\n $N7ポイント：$D3かけて$N8のダメージ。\n $N10ポイント：$D4かけて$N11のダメージ。\n $N13ポイント：$D5かけて$N14のダメージ。", "$N2秒ごとに$N1の出血ダメージを受けます。", 0x49157ab0, 0x75c83da5, "uu" },
  [1082] = { "敵を爪で引き裂き、通常ダメージの$N1%に$N2を加えたダメージを与えます。コンボポイントを$N3獲得します。", nil, 0x93d55dee, nil, "um" },
  [1086] = { "$D2の間、術者を守り、armorを$N1、Shadow耐性を$N2増加させ、health回復量を5秒ごとに$N3増加させます。", "armorが$N1、Shadow耐性が$N2増加し、healthの回復量が5秒ごとに$N3増加します。", 0x6ab340ac, 0x91ee7074, "uu" },
  [1088] = { "敵に影の矢を放ち、$N1のShadowダメージを与えます。", nil, 0xc6f8d47d, nil, "um" },
  [1090] = { "敵の対象を最大$D1の間眠らせます。ダメージを受けると対象は目を覚まします。同時に眠らせておける対象は1体だけです。", "眠っています。", 0x26124111, 0x5339954e, "uu" },
  [1094] = { "敵を焼き、$N1のFireダメージを与え、さらに$D1かけて$N2のFireダメージを与えます。", "$N2秒ごとに$N1のFireダメージを受けます。", 0xe3931f57, 0x0d35ca56, "uu" },
  [1098] = { "レベル$N1までの悪魔を服従させ、命令に従わせます。服従している間、悪魔の攻撃間隔は$N2%長くなり、詠唱速度は$N3%遅くなります。効果時間は最大$D1です。同じ悪魔を繰り返し服従させると、そのたびに制御が難しくなります。", "隷属させられています。", 0x93ce24f8, 0xb260b47a, "uu" },
  [1101] = { "Mana Funnelを習得します。", nil, 0x293f7e68, nil, "um" },
  [1105] = { "Seal of Wisdom（Rank 3）を習得します。", nil, 0x473624dc, nil, "um" },
  [1106] = { "敵に影の矢を放ち、$N1のShadowダメージを与えます。", nil, 0xc6f8d47d, nil, "um" },
  [1108] = { "$D1の間、対象が与える物理ダメージを$N1減少させます。1体の対象に対して、各ウォーロックがかけられるCurseは1つだけです。", "与える物理ダメージが$N1減少しています。", 0x45b27a1b, 0x212710bf, "uu" },
  [1120] = { "対象の魂を吸い取り、$D1かけて$N1のShadowダメージを与えます。Drain Soulでダメージを受けた、経験値か名誉を得られる対象は、Soul Shardをもたらすことがあります。Drain Soulで倒された、経験値か名誉を得られる対象は、必ずSoul Shardをもたらします。Soul Shardは他の呪文に必要です。", "$N2秒ごとに$N1のShadowダメージを受けます。", 0x0ad8031e, 0x774bc67a, "uu" },
  [1122] = { "Twisting Netherから隕石を呼び寄せ、$N1のFireダメージを与え、範囲内のすべての敵を$D1の間スタンさせます。クレーターからInfernalが現れ、$D2の間、術者の命令に従います。制御が切れたら、制御を保つにはInfernalをSubjugatedの状態にする必要があります。屋外でのみ使用できます。", nil, 0x5a6ba85a, nil, "um" },
  [1126] = { "$D1の間、味方の対象のarmorを$N1上げます。", "armorが$N1増加します。", 0xfb7f6b76, 0xa12a98e7, "uu" },
  [1127] = { "$D1かけてhealthを$N1回復します。回復中は座っている必要があります。", "毎秒healthを$N1回復します。", 0xe5e04206, 0xfde4540f, "uu" },
  [1129] = { "$D1かけてhealthを$N1回復します。回復中は座っている必要があります。", "毎秒healthを$N1回復します。", 0xe5e04206, 0xfde4540f, "uu" },
  [1130] = { "対象にHunter's Markを付け、その対象を攻撃するすべての者のRanged Attack Powerを$N1上げます。さらに、この能力の対象はステルスしても透明になっても、常にハンターから見えます。対象はミニマップにも表示されます。効果時間は$D1です。", "この対象を攻撃するすべての者のRanged Attack Powerが$N1増加します。", 0xf034dbfd, 0x3d2d7958, "uu" },
  [1131] = { "$D1かけてhealthを$N1回復します。回復中は座っている必要があります。", "毎秒healthを$N1回復します。", 0xe5e04206, 0xfde4540f, "uu" },
  [1133] = { "$D1かけてmanaを$N1回復します。回復中は座っている必要があります。", "毎秒manaを$N1回復します。", 0x792a9d04, 0x338019ff, "uu" },
  [1135] = { "$D1かけてmanaを$N1回復します。回復中は座っている必要があります。", "毎秒manaを$N1回復します。", 0x792a9d04, 0x338019ff, "uu" },
  [1137] = { "$D1かけてmanaを$N1回復します。回復中は座っている必要があります。", "毎秒manaを$N1回復します。", 0x792a9d04, 0x338019ff, "uu" },
  [1138] = { "$D1の間、FrostとShadowへの抵抗力を$N1上げます。", "FrostとShadowの耐性が上昇しています。", 0xc31c32d3, 0x2ca18795, "uu" },
  [1139] = { "$D1の間、対象の攻撃間隔を$N1%延ばし、移動速度を$N2%下げます。", "攻撃速度が$N1%低下しています。\r\n移動速度が$N2%低下しています。", 0x8cbf1cf8, 0x3b8ba8d2, "uu" },
  [1152] = { "味方の対象を浄化し、病気効果を$N1個と毒効果を$N2個取り除きます。", nil, 0x55d8540d, nil, "um" },
  [1159] = { "$D1かけて$N1のダメージを回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0xcb31688f, 0x4b6eb5c1, "uu" },
  [1160] = { "$N1ヤード以内のすべての敵の近接攻撃力を$D1の間$N2低下させます。", "近接攻撃力が$N1低下します。", 0x0b9fb8a1, 0x175f2725, "uu" },
  [1161] = { "$N1ヤード以内の近くにいるすべての敵に、$D1の間あなたを集中攻撃させます。", "挑発されています。", 0x9fb1c112, 0x36f56123, "uu" },
  [1243] = { "対象に力を注ぎ込み、$D1の間Staminaを$N1上げます。", "Staminaが$N1増加します。", 0xf7c34722, 0x54404694, "uu" },
  [1244] = { "対象に力を注ぎ込み、$D1の間Staminaを$N1上げます。", "Staminaが$N1増加します。", 0xf7c34722, 0x54404694, "uu" },
  [1245] = { "対象に力を注ぎ込み、$D1の間Staminaを$N1上げます。", "Staminaが$N1増加します。", 0xf7c34722, 0x54404694, "uu" },
  [1329] = { "両方の武器で即座に攻撃し、武器ダメージの$N1%に加えて、それぞれの武器で$N2の追加ダメージを与えます。Poisoned状態の対象へのダメージは$N3%増加します。コンボポイントを$N4獲得します。", nil, 0x4ef95aa3, nil, "um" },
  [1366] = { "Summon Impを習得します。", nil, 0xd7f289c5, nil, "um" },
  [1385] = { "Summon Voidwalkerを習得します。", nil, 0x4e5efdd7, nil, "um" },
  [1403] = { "Summon Succubusを習得します。", nil, 0x0e5ac842, nil, "um" },
  [1430] = { "$D1かけて対象を$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x3367b9a9, 0x1302c045, "uu" },
  [1449] = { "詠唱者の回りに神秘魔法の爆発を\n起こし、$N2 yard内の全ての敵に\n$N1Arcaneダメージを与えます。", nil, 0x51d9ff5b, nil, "um" },
  [1454] = { "healthを$N1消費してmanaを$N2回復します。\nSpiritにより変換量が増加します。", nil, 0x22159aef, nil, "um" },
  [1455] = { "$N1のHealthを$N2のManaに変換します。Spiritが高いほど変換量が増加します。", nil, 0x22159aef, nil, "um" },
  [1456] = { "$N1のHealthを$N2のManaに変換します。Spiritが高いほど変換量が増加します。", nil, 0x22159aef, nil, "um" },
  [1459] = { "$D1の間、対象のIntellectを$N1上げます。", "Intellectが$N1増加します。", 0x9663f4be, 0xec5dd10a, "uu" },
  [1460] = { "$D1の間、対象のIntellectを$N1上げます。", "Intellectが$N1増加します。", 0x9663f4be, 0xec5dd10a, "uu" },
  [1461] = { "$D1の間、対象のIntellectを$N1上げます。", "Intellectが$N1増加します。", 0x9663f4be, 0xec5dd10a, "uu" },
  [1462] = { "ターゲットのBeastに関する情報を\n集めます。ツールチップに、ダメージ、\nヘルス、アーマー、特殊な耐性、食性を表示します。", "伝承が明かされました。", 0x4707687a, 0xe667adde, "uu" },
  [1463] = { "物理ダメージを$N1吸収し、代わりにmanaを消費します。吸収したダメージごとにmanaを$N2消費します。効果時間は$D1です。", "物理ダメージを吸収し、代わりにmanaを消費します。", 0x6186eef7, 0xd9625b22, "uu" },
  [1464] = { "相手を強打し、武器ダメージに加えて$N1のダメージを与えます。", nil, 0x27b9eb8b, nil, "um" },
  [1494] = { "近くにいるすべての獣の位置をミニマップに表示します。一度に有効にできる追跡は1種類だけです。", "Beastsを追跡しています。", 0x7a0f6d82, 0x5bdf0ba6, "uu" },
  [1495] = { "敵に反撃し、近接武器ダメージに$N1を加えたダメージを与えます。回避した後にのみ使用できます。", nil, 0xb7f0fcdf, nil, "um" },
  [1499] = { "最初に近づいた敵を凍らせるFrostの罠を仕掛け、最大$D1の間すべての行動を封じます。ダメージを受けると氷は砕けます。罠は$D2の間存在します。同時に設置できるFrostの罠は1つだけです。", nil, 0xe57bc3d9, nil, "um" },
  [1510] = { "$D2の間、対象の範囲に弾薬を連続で撃ち込み、$N2ヤード以内の敵に$N3秒ごとに$N1のArcaneダメージを与えます。", nil, 0x7756797c, nil, "um" },
  [1513] = { "獣を怯えさせ、最大$D1の間恐怖で逃げ惑わせます。ダメージを受けると効果が中断されることがあります。同時に恐怖状態にできる獣は1体だけです。", "恐怖に陥っています。", 0xcc6a4f70, 0x5a2205f2, "uu" },
  [1515] = { "獣を手なずけ、仲間にし始めます。$D1の間、獣を手なずけることに集中している間はarmorが$N1%減少します。何らかの理由で獣の注意がそれると、手なずけは失敗します。手なずけた直後の獣はとても不機嫌で忠誠心がありません。すぐにペットに餌を与えて機嫌をよくしてください。", "ペットを手なずけています。", 0x653847d0, 0xc7d3fce8, "uu" },
  [1538] = { "3つの儀式の火葬台で使うと、Rod of Helcularに力を充填します。", nil, 0x53759e50, nil, "um" },
  [1543] = { "$D1の間、指定した範囲から$N1ヤード以内にいる、隠れている敵と透明な敵をすべてあらわにします。", "隠れているユニットと透明なユニットが見えます。", 0x5a79a1a4, 0xe485f4e9, "uu" },
  [1608] = { "近接攻撃のダメージを$N1増加させ、高い脅威を生み出す強力な攻撃です。", nil, 0x7cd71b11, nil, "um" },
  [1671] = { "盾で対象を殴りつけ、$N1のダメージを与えます。さらに呪文の詠唱を中断させ、$D1の間、その系統の呪文を唱えられなくします。", nil, 0x7e95b69c, nil, "um" },
  [1672] = { "盾で対象を殴りつけ、$N1のダメージを与えます。さらに呪文の詠唱を中断させ、$D1の間、その系統の呪文を唱えられなくします。", nil, 0x7e95b69c, nil, "um" },
  [1680] = { "鋼の旋風となって$N2ヤード以内の最大$N1体の敵を攻撃し、それぞれに武器ダメージを与えます。", nil, 0x019c0e2f, nil, "um" },
  [1706] = { "術者を浮遊させ、地面から少し浮かび上がらせます。浮遊している間は落下速度が遅くなり、水のような面の上を移動できます。騎乗するかダメージを受けると効果が解けます。効果時間は$D1です。", "浮遊しています。", 0x2714f771, 0xfb3d5081, "uu" },
  [1714] = { "対象にDemonicで話させ、すべての呪文の詠唱時間を$N1%延ばします。同じ対象にかけられるCurseは、ウォーロックごとに1つだけです。効果時間は$D1です。", "Demonicを話しており、詠唱時間が$N1%増加しています。", 0x9cc3933f, 0xa89ef244, "uu" },
  [1715] = { "敵を痛めつけ、$N1のダメージを与え、$D1の間移動速度を$N2%低下させます。", "移動速度が$N1%低下しています。", 0x99e679bf, 0xbd9449c1, "uu" },
  [1719] = { "次の$D1の間、ウォリアーのクリティカル率が$N1%上がり、Fear効果を無効にしますが、受けるダメージがすべて$N3%増加します。", "Fearの効果が効かず、クリティカル率が$N1%上昇しますが、受けるすべてのダメージが$N2%増加します。", 0x2a57cc08, 0x526ed478, "uu" },
  [1725] = { "物を投げて気を散らします、$N2秒\n間近くにいる全てのモンスターの気を\n引き、Stealth探知を$N1レベル低い状態まで下げます。stealth中に使用できます。", "ステルス探知能力が低下しています。", 0x4cc0cfc7, 0x1e688c75, "uu" },
