  [1768] = { "素早い蹴りで敵1体に$N1のダメージを与えます。さらに呪文の詠唱を中断させ、$D1の間その系統の呪文を使えなくします。", nil, 0xb1c3df31, nil, "um" },
  [1769] = { "素早い蹴りで敵1体に$N1のダメージを与えます。さらに呪文の詠唱を中断させ、$D1の間その系統の呪文を使えなくします。", nil, 0xb1c3df31, nil, "um" },
  [1776] = { "$N1のダメージを与え、自分の攻撃を止め、$D1の間対象を行動不能にします。対象がこちらを向いている必要があります。ダメージを受けると効果が解けます。コンボポイントを$N3獲得します。", "行動不能です。", 0x156eba70, 0x147cb83f, "uu" },
  [1777] = { "$N1のダメージを与えて攻撃を止め、$D1の間対象を行動不能にします。対象はあなたの方を向いている必要があります。ダメージを受けると効果は解けます。コンボポイントを$N3獲得します。", "行動不能です。", 0x156eba70, 0x147cb83f, "uu" },
  [1784] = { "影に隠れて、敵に発見されずに\n近づけるようになりますが、\n移動速度が$N1%低下します。\n効果はキャンセルするまで持続します。", "隠密状態です。移動速度が$N1%低下しています。", 0xe555a300, 0xbb2c451c, "uu" },
  [1785] = { "ローグが忍び歩きできるようになりますが、速度が$N1%低下します。解除するまで持続します。", "隠密状態です。移動速度が$N1%低下しています。", 0xe555a300, 0xbb2c451c, "uu" },
  [1786] = { "ローグが忍び歩きできるようになりますが、速度が$N1%低下します。解除するまで持続します。", "隠密状態です。移動速度が$N1%低下しています。", 0xe555a300, 0xbb2c451c, "uu" },
  [1787] = { "ローグが忍び歩きできるようになりますが、速度が$N1%低下します。解除するまで持続します。", "隠密状態です。移動速度が$N1%低下しています。", 0xe555a300, 0xbb2c451c, "uu" },
  [1804] = { "鍵の掛かった\n箱やドアを開けることができます。", nil, 0x5cb18c97, nil, "um" },
  [1822] = { "対象を引き裂いて$N1のダメージを与え、さらに$D1かけて$N2の追加ダメージを与えます。コンボポイントを$N4獲得します。", "出血により、$N2秒ごとに$N1のダメージを受けています。", 0x59b5d40d, 0x84eecd00, "uu" },
  [1823] = { "対象を引き裂き、$N1のダメージと、$D1かけてさらに$N2のダメージを与えます。コンボポイントを$N4獲得します。", "出血により、$N2秒ごとに$N1のダメージを受けています。", 0x59b5d40d, 0x84eecd00, "uu" },
  [1824] = { "対象を引き裂き、$N1のダメージと、$D1かけてさらに$N2のダメージを与えます。コンボポイントを$N4獲得します。", "出血により、$N2秒ごとに$N1のダメージを受けています。", 0x59b5d40d, 0x84eecd00, "uu" },
  [1833] = { "$D1の間、対象をスタンさせます。隠密状態である必要があります。コンボポイントを$N2獲得します。", "スタンしています。", 0x39363b35, 0x27f95286, "uu" },
  [1842] = { "罠に忍び寄って解除します。近づきすぎると罠が作動します。", nil, 0x9c69c3a0, nil, "um" },
  [1850] = { "$D1の間、移動速度を$N1%上げます。忍び歩きは解除されません。", "移動速度が$N1%上昇します。", 0x02454378, 0xf152500f, "uu" },
  [1853] = { "対象を挑発し、その敵があなたを集中攻撃しやすくします。", nil, 0xdf1961ba, nil, "um" },
  [1856] = { "ローグの姿を消し、$D1の間、強化された隠密状態に入ります。移動を妨げる効果も解除します。", "隠密能力が向上しています。", 0x5ab837e2, 0xad8eb7ec, "uu" },
  [1857] = { "ローグが姿を消し、$D1の間、強化されたステルス状態になります。移動妨害効果も解除します。Vanish（Rank 1）より効果的です。", "隠密能力が向上しています。", 0xd54258b2, 0xad8eb7ec, "uu" },
  [1860] = { "落下時のダメージを減少します。", nil, 0x879f36dd, nil, "um" },
  [1866] = { "武器ダメージの$N1%に加え、さらに$N2のHolyダメージを与える瞬時の一撃です。", nil, 0xc64d407b, nil, "um" },
  [1940] = { "半径3ヤードに$N1のFireダメージを与えます。", nil, 0x41426fd0, nil, "um" },
  [1943] = { "DoTを与えるFinishing move。\nダメージはAttack Powerにより増加します。\nコンボポイントにより持続時間が\n延長されます。\n$N1ポイント:$N2ダメージ$N3秒間\n$N4ポイント:$N5ダメージ$N6秒間\n$N7ポイント:$N8ダメージ$N9秒間\n$N10ポイント:$N11ダメージ$N12秒間\n$N13ポイント:$N14ダメージ$N15秒間", "$N2秒ごとに$N1のダメージを受けます。", 0x8733aeb4, 0x05440273, "uu" },
  [1949] = { "術者の周囲に火を放ち、$N3秒ごとに自身に$N1のFireダメージを、周囲のすべての敵に$N2のFireダメージを与えます。$D2持続します。", "自身と周囲のすべての敵にダメージを与えます。", 0xe2a96711, 0xa06710c3, "uu" },
  [1953] = { "何かの障害物がなければ、術者を最大で$N1\nヤード瞬間移動します。また、術者を\n気絶(Stun)や拘束から解放します。", "瞬間移動しています。", 0x430f3726, 0xfc171a45, "uu" },
  [1966] = { "フェイントをかけます。ダメージは与えませんが、脅威を少し下げ、敵から攻撃されにくくなります。", nil, 0xcd90a72a, nil, "um" },
  [1978] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0xa701572a, "uu" },
